import React, { useState, useEffect } from 'react';

const ImageViewer = ({ images }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [selectedImage, setSelectedImage] = useState(null);

  const openModal = (index) => {
    const imgElement = images[index];
    if (!imgElement) {
      console.error(`Image at index ${index} not found`);
      return;
    }

    const bgImage = imgElement.style.backgroundImage;
    const imgSrc = bgImage.slice(5, -2);
    const imgText = imgElement.getAttribute("data-text") || "No description available";
    const isCarousel = imgElement.getAttribute("data-carousel") === "true";
    let imageList = imgElement.getAttribute("data-images");

    if (imageList) {
      try {
        imageList = JSON.parse(imageList);
      } catch (error) {
        console.error("Failed to parse data-images", error);
        return;
      }
    }

    setSelectedImage({
      src: imgSrc,
      text: imgText,
      isCarousel,
      imageList
    });
    setCurrentSlideIndex(0);
    setIsOpen(true);
  };

  const showSlide = (index) => {
    const slides = document.getElementsByClassName("carousel-slide");

    if (index >= slides.length) setCurrentSlideIndex(0);
    if (index < 0) setCurrentSlideIndex(slides.length - 1);

    for (let i = 0; i < slides.length; i++) {
      slides[i].style.display = "none";
    }

    slides[currentSlideIndex].style.display = "block";
  };

  const nextSlide = () => {
    const newIndex = currentSlideIndex + 1;
    setCurrentSlideIndex(newIndex);
    showSlide(newIndex);
  };

  const prevSlide = () => {
    const newIndex = currentSlideIndex - 1;
    setCurrentSlideIndex(newIndex);
    showSlide(newIndex);
  };

  const closeModal = () => {
    setIsOpen(false);
  };

  useEffect(() => {
    const handleKeyDown = (event) => {
      if (isOpen && event.key === "Escape") {
        closeModal();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div id="myModal" style={{display: 'block'}}>
      {selectedImage.isCarousel && selectedImage.imageList && selectedImage.imageList.length > 0 ? (
        <div className="carousel-container">
          {selectedImage.imageList.map((src, index) => (
            <div 
              key={index} 
              className="carousel-slide" 
              style={{display: index === currentSlideIndex ? 'block' : 'none'}}
            >
              <img src={src} alt={`Slide ${index + 1}`} />
            </div>
          ))}
          <button className="prev" onClick={prevSlide}>&#10094;</button>
          <button className="next" onClick={nextSlide}>&#10095;</button>
        </div>
      ) : (
        <img id="modalImg" src={selectedImage.src} alt="Selected" />
      )}

      <div id="caption">{selectedImage.text}</div>
      <span className="close" onClick={closeModal}>&times;</span>
    </div>
  );
};

export default ImageViewer;
